#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_melancholy.py — порт КРХ-авойда (OpenKrx) из Nullcki в melancholy (kernet).
Запускается в CI ДО сборки; cwd = корень kernet, NULLCKI_SRC = распакованный Nullcki.
Делает:
  1) копирует src/game/client/avoid/* + krx/{flow_field,msvc_sort} + client_profile.h
  2) адаптирует копии (Krx-миры -> m_GameWorld/m_PredictedWorld, AFK-гейт, flow-field
     провайдер вместо TAS, DragAim-заглушка)
  3) добавляет krx_compat.h/.cpp (AFK-гейт + flow field + MSVC rand)
  4) вкладка настроек "Avoid" (меню как в KRX) вместо старой "Avoid New"
  5) удаляет старый авойд avoidblatant и все его следы
  6) патчит мир предсказания (физика KRX: смерть/телепорты/файер-дилей/взрывы)
  7) вшивает цепочку Avoid в SnapInput (как в Nullcki) + трассировка
     openkrx_avoid_dump + физический прыжок Rocket Save
  8) шимы совместимости kernet: IClient::CInputTiming/GetInputTiming,
     CUi::DoToolTip (no-op), CWorldCore::m_IsNullPrediction,
     GetScreen/MapScreen/ServerInfo/время — через krx_compat
"""
import os
import re
import sys

ROOT = os.getcwd()
NK = os.environ.get("NULLCKI_SRC", "/tmp/Nullcki-main")

OK = []
FAIL = []


def ok(msg):
    OK.append(msg)
    print("  + " + msg)


def fail(msg):
    FAIL.append(msg)
    print("  ! FAIL: " + msg)


def rd(p):
    with open(p, "r", encoding="utf-8", newline="") as f:
        return f.read().replace("\r\n", "\n")


def wr(p, s):
    d = os.path.dirname(p)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(p, "w", encoding="utf-8", newline="") as f:
        f.write(s)


def sub(path, old, new, label, count=1, required=True):
    if not os.path.exists(path):
        fail("%s: нет файла (%s)" % (path, label))
        return
    s = rd(path)
    n = s.count(old)
    if n < count:
        if required:
            fail("%s: якорь не найден x%d/%d (%s)" % (path, n, count, label))
        else:
            print("  ~ skip (не найдено, не критично): %s (%s)" % (os.path.basename(path), label))
        return
    s = s.replace(old, new, count if count else -1)
    wr(path, s)
    ok("%s :: %s" % (os.path.basename(path), label))


def rex(path, pattern, repl, label, flags=re.DOTALL):
    if not os.path.exists(path):
        fail("%s: нет файла (%s)" % (path, label))
        return
    s = rd(path)
    ns, cnt = re.subn(pattern, repl, s, count=1, flags=flags)
    if cnt == 0:
        fail("%s: regex не совпал (%s)" % (path, label))
        return
    wr(path, ns)
    ok("%s :: %s (regex)" % (os.path.basename(path), label))


def nread(rel):
    return rd(os.path.join(NK, rel))


def slice_between(s, start_marker, end_marker, label):
    i = s.find(start_marker)
    j = s.find(end_marker, i + len(start_marker))
    if i < 0 or j < 0:
        fail("slice %s: маркеры не найдены" % label)
        return None
    return s[i:j]


# ---------------------------------------------------------------- 0. sanity
print("== patch_melancholy: cwd=%s nullcki=%s" % (ROOT, NK))
need = [
    os.path.join(NK, "src/game/client/avoid/avoid.cpp"),
    os.path.join(NK, "src/game/client/krx/flow_field.cpp"),
    "src/game/client/gameclient.cpp",
    "src/game/client/components/controls.cpp",
]
for p in need:
    if not os.path.exists(p):
        fail("нет обязательного файла: %s" % p)
if FAIL:
    sys.exit(1)

MARKER = "src/game/client/avoid/krx_compat.h"
if os.path.exists(MARKER):
    print("== порт уже применён (marker) — пропускаю")
    sys.exit(0)

# ---------------------------------------------------------------- 1. копии файлов
print("== 1. копирую файлы из Nullcki")
AV = "src/game/client/avoid"
KR = "src/game/client/krx"
for name in ["avoid", "blatant", "classic_agents", "fent", "pilot_bot",
             "rocket_save", "simulation", "trace"]:
    for ext in [".cpp", ".h"]:
        src = os.path.join(NK, "src/game/client/avoid", name + ext)
        dst = os.path.join(AV, name + ext)
        wr(dst, rd(src))
        ok("copy %s" % dst)
for name in ["flow_field.cpp", "flow_field.h", "msvc_sort.h"]:
    dst = os.path.join(KR, name)
    wr(dst, rd(os.path.join(NK, "src/game/client/krx", name)))
    ok("copy %s" % dst)
wr("src/engine/shared/client_profile.h",
   rd(os.path.join(NK, "src/engine/shared/client_profile.h")))
ok("copy src/engine/shared/client_profile.h")
wr(os.path.join(AV, "menus_settings_avoid.cpp"),
   rd(os.path.join(NK, "src/game/client/components/menus_settings_avoid.cpp")))
ok("copy src/game/client/avoid/menus_settings_avoid.cpp (UI вкладки Avoid)")

# ---------------------------------------------------------------- 2. адаптация копий
print("== 2. адаптирую копии под melancholy (DDNet 19.8)")

COPIED = [os.path.join(AV, f) for f in
          ["avoid.cpp", "avoid.h", "blatant.cpp", "blatant.h",
           "classic_agents.cpp", "classic_agents.h", "fent.cpp", "fent.h",
           "pilot_bot.cpp", "pilot_bot.h", "rocket_save.cpp", "rocket_save.h",
           "simulation.cpp", "simulation.h", "trace.cpp", "trace.h"]]

# миры KRX -> штатные миры DDNet (без TAS: m_GameWorld/m_PredictedWorld)
