import base64 as _nyb64

def _wrbin(p, data):
    d = os.path.dirname(p)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(p, "wb") as f:
        f.write(data)
    ok("binary %s (%d байт)" % (p, len(data)))

NY_ASSETS = {
    "data/melancholy/menu_bg_ny.png": (
    ""),
    "data/melancholy/logo_ny.png": (
    ""),
    "data/menuimages/play_game.png": (
    ""),
    "data/menuimages/editor.png": (
    ""),
    "data/menuimages/local_server.png": (
    ""),
    "data/menuimages/settings.png": (
    ""),
}
for _ny_p, _ny_b in NY_ASSETS.items():
    _wrbin(_ny_p, _nyb64.b64decode(_ny_b))

